import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import './Admin.css';

const Admin = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('tools');
  const [tools, setTools] = useState([]);
  const [cases, setCases] = useState([]);
  const [stats, setStats] = useState({});
  const [settings, setSettings] = useState({});
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({});
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }

    fetchData();
  }, [user, navigate]);

  const fetchData = async () => {
    try {
      const [toolsRes, casesRes, statsRes, settingsRes] = await Promise.all([
        axios.get('/api/tools'),
        axios.get('/api/cases'),
        axios.get('/api/stats'),
        axios.get('/api/settings')
      ]);

      setTools(toolsRes.data);
      setCases(casesRes.data);
      setStats(statsRes.data);
      setSettings(settingsRes.data);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
    setLoading(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const handleAddTool = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/tools', formData);
      setMessage('Tool added successfully');
      setFormData({});
      fetchData();
    } catch (error) {
      setMessage('Error adding tool');
    }
  };

  const handleDeleteTool = async (id) => {
    if (window.confirm('Are you sure you want to delete this tool?')) {
      try {
        await axios.delete(`/api/tools/${id}`);
        setMessage('Tool deleted successfully');
        fetchData();
      } catch (error) {
        setMessage('Error deleting tool');
      }
    }
  };

  const handleUpdateStats = async (e) => {
    e.preventDefault();
    try {
      await axios.put('/api/stats', formData);
      setMessage('Stats updated successfully');
      fetchData();
    } catch (error) {
      setMessage('Error updating stats');
    }
  };

  const handleUpdateSettings = async (e) => {
    e.preventDefault();
    try {
      await axios.put('/api/settings', formData);
      setMessage('Settings updated successfully');
      fetchData();
    } catch (error) {
      setMessage('Error updating settings');
    }
  };

  if (loading) return <div className="admin-loading">Loading...</div>;

  return (
    <div className="admin-container">
      <div className="admin-header">
        <h1>Admin Dashboard</h1>
        <button onClick={handleLogout} className="logout-btn">Logout</button>
      </div>

      {message && <div className="message">{message}</div>}

      <div className="admin-tabs">
        <button
          className={activeTab === 'tools' ? 'active' : ''}
          onClick={() => setActiveTab('tools')}
        >
          Tools
        </button>
        <button
          className={activeTab === 'cases' ? 'active' : ''}
          onClick={() => setActiveTab('cases')}
        >
          Cases
        </button>
        <button
          className={activeTab === 'stats' ? 'active' : ''}
          onClick={() => setActiveTab('stats')}
        >
          Stats
        </button>
        <button
          className={activeTab === 'settings' ? 'active' : ''}
          onClick={() => setActiveTab('settings')}
        >
          Settings
        </button>
      </div>

      <div className="admin-content">
        {activeTab === 'tools' && (
          <div className="tools-section">
            <h2>Manage Tools</h2>
            <form onSubmit={handleAddTool} className="add-form">
              <input
                type="text"
                placeholder="Tool Name"
                value={formData.name || ''}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="Category"
                value={formData.category || ''}
                onChange={(e) => setFormData({...formData, category: e.target.value})}
                required
              />
              <textarea
                placeholder="Use Description"
                value={formData.use || ''}
                onChange={(e) => setFormData({...formData, use: e.target.value})}
                required
              />
              <button type="submit">Add Tool</button>
            </form>

            <div className="items-list">
              {tools.map(tool => (
                <div key={tool._id} className="item-card">
                  <h3>{tool.name}</h3>
                  <p><strong>Category:</strong> {tool.category}</p>
                  <p>{tool.use}</p>
                  <button onClick={() => handleDeleteTool(tool._id)} className="delete-btn">Delete</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'cases' && (
          <div className="cases-section">
            <h2>Case Studies</h2>
            <div className="items-list">
              {cases.map(caseStudy => (
                <div key={caseStudy._id} className="item-card">
                  <h3>{caseStudy.title}</h3>
                  <p><strong>Client:</strong> {caseStudy.client}</p>
                  <p><strong>Category:</strong> {caseStudy.category}</p>
                  <p>{caseStudy.description}</p>
                  <div className="results">
                    <span>{caseStudy.result1Number} {caseStudy.result1Label}</span>
                    <span>{caseStudy.result2Number} {caseStudy.result2Label}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="stats-section">
            <h2>Update Statistics</h2>
            <form onSubmit={handleUpdateStats} className="update-form">
              <div className="form-row">
                <input
                  type="text"
                  placeholder="Stat 1 Number"
                  value={formData.stat1Number || stats.stat1Number || ''}
                  onChange={(e) => setFormData({...formData, stat1Number: e.target.value})}
                  required
                />
                <input
                  type="text"
                  placeholder="Stat 1 Label"
                  value={formData.stat1Label || stats.stat1Label || ''}
                  onChange={(e) => setFormData({...formData, stat1Label: e.target.value})}
                  required
                />
              </div>
              <div className="form-row">
                <input
                  type="text"
                  placeholder="Stat 2 Number"
                  value={formData.stat2Number || stats.stat2Number || ''}
                  onChange={(e) => setFormData({...formData, stat2Number: e.target.value})}
                  required
                />
                <input
                  type="text"
                  placeholder="Stat 2 Label"
                  value={formData.stat2Label || stats.stat2Label || ''}
                  onChange={(e) => setFormData({...formData, stat2Label: e.target.value})}
                  required
                />
              </div>
              <div className="form-row">
                <input
                  type="text"
                  placeholder="Stat 3 Number"
                  value={formData.stat3Number || stats.stat3Number || ''}
                  onChange={(e) => setFormData({...formData, stat3Number: e.target.value})}
                  required
                />
                <input
                  type="text"
                  placeholder="Stat 3 Label"
                  value={formData.stat3Label || stats.stat3Label || ''}
                  onChange={(e) => setFormData({...formData, stat3Label: e.target.value})}
                  required
                />
              </div>
              <button type="submit">Update Stats</button>
            </form>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="settings-section">
            <h2>Update Settings</h2>
            <form onSubmit={handleUpdateSettings} className="update-form">
              <input
                type="text"
                placeholder="Name"
                value={formData.name || settings.name || ''}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                required
              />
              <input
                type="email"
                placeholder="Email"
                value={formData.email || settings.email || ''}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="Phone"
                value={formData.phone || settings.phone || ''}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                required
              />
              <input
                type="text"
                placeholder="Location"
                value={formData.location || settings.location || ''}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
                required
              />
              <button type="submit">Update Settings</button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;
